var MeetingsTranscriptsListMeeting = &Operation{
	ID: "MeetingsTranscriptsListMeeting", Area: "meetings", Group: "transcripts", Command: "list-meeting",
	Summary:     "List Meeting Transcripts",
	Description: "Lists available transcripts of an ended [meeting instance](/docs/meetings#meeting-series-scheduled-meetings-and-meeting-instances).\n\nUse this operation to list transcripts of an ended [meeting instance](/docs/meetings#meeting-series-scheduled-meetings-and-meeting-instances) when they are ready. Please note that only **meeting instances** in state `ended` are supported for `meetingId`. **Meeting series**, **scheduled meetings** and `in-progress` **meeting instances** are not supported.\n\n#### Request Header\n\n* `timezone`: [Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.",
	Method:      "GET", Path: "/meetingTranscripts", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of transcripts to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for transcripts to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for List transcripts to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`."},
		{Name: "meetingId", In: InQuery, Flag: "meeting-id", Usage: "Unique identifier for the [meeting instance](/docs/meetings#meeting-series-scheduled-meetings-and-meeting-instances) to which the transcript belongs. Please note that currently the meeting ID of a scheduled [personal room](https://help.webex.com/en-us/article/nul0wut/Webex-Personal-Rooms-in-Webex-Meetings) meeting is not supported for this API. If `meetingId` is not specified, the operation returns an array of transcripts for all meetings of the current user."},
		{Name: "hostEmail", In: InQuery, Flag: "host-email", Usage: "Email address for the meeting host. This parameter is only used if the user or application calling the API has the `admin-level` scopes. If set, the admin may specify the email of a user in a site they manage and the API will return details for a meeting that is hosted by that user. If `meetingId` is not specified, it can not support `hostEmail`."},
		{Name: "siteUrl", In: InQuery, Flag: "site-url", Usage: "URL of the Webex site from which the API lists transcripts. If not specified, the API lists transcripts from user's preferred site. All available Webex sites and the preferred site of the user can be retrieved by the [Get Site List](/docs/api/v1/meeting-preferences/get-site-list) API."},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

