var MeetingsRecordingReportListAuditSummaries = &Operation{
	ID: "MeetingsRecordingReportListAuditSummaries", Area: "meetings", Group: "recording-report", Command: "list-audit-summaries",
	Summary:     "List of Recording Audit Report Summaries",
	Description: "Lists of recording audit report summaries. You can specify a date range and the maximum number of recording audit report summaries to return.\n\nOnly recording audit report summaries of meetings hosted by or shared with the authenticated user will be listed.\n\nThe list returned is sorted in descending order by the date and time that the recordings were created.\n\nLong result sets are split into [pages](/docs/basics#pagination).\n\n* If `siteUrl` is specified, the recording audit report summaries of the specified site will be listed; otherwise, recording audit report summaries of the user's preferred site will be listed. All available Webex sites and the preferred site of the user can be retrieved by the `Get Site List` API.\n\n#### Request Header\n\n* `timezone`: [Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.",
	Method:      "GET", Path: "/recordingReport/accessSummary", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of recording audit report summaries to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for recording audit report summaries to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`. Please note that the interval between `to` and `from` cannot exceed 90 days and the interval between the current time and `from` cannot exceed 365 days."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for recording audit report summaries to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`. Please note that the interval between `to` and `from` cannot exceed 90 days and the interval between the current time and `from` cannot exceed 365 days."},
		{Name: "hostEmail", In: InQuery, Flag: "host-email", Usage: "Email address for the meeting host. This parameter is only used if the user or application calling the API has the admin on-behalf-of scopes. If set, the admin may specify the email of a user in a site they manage and the API will return recording audit report summaries of that user. If a special value of `all` is set for `hostEmail`, the admin can list recording audit report summaries of all users on the target site, not of a single user."},
		{Name: "siteUrl", In: InQuery, Flag: "site-url", Usage: "URL of the Webex site which the API lists recording audit report summaries from. If not specified, the API lists summary audit report for recordings from the user's preferred site. All available Webex sites and the preferred site of the user can be retrieved by `Get Site List` API."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

